import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-03-11","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-03-11","date":"2026-03-11T00:00:00.000Z","updated":"2026-05-14T00:00:00.000Z","tags":["Ceph RGW","multipart upload","object storage","multi-site replication","IAM policy"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-11.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-11.md","lastUpdated":1780460162000}'),n={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-11.md"};function p(i,t,s,l,c,d){return o(),r("div",null,[...t[0]||(t[0]=[a(`<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph RGW Refactoring Meeting 于 2026 年 3 月 11 日举行，涵盖四个主要议题：小对象内联存储优化、multipart upload 数据丢失问题修复、Keystone 角色注入 IAM policy，以及 multi-site 复制流量负载均衡问题。</p><h2 id="议题一-小对象内联存储-tiny-rgw-objects-packing" tabindex="-1">议题一：小对象内联存储（Tiny RGW Objects Packing） <a class="header-anchor" href="#议题一-小对象内联存储-tiny-rgw-objects-packing" aria-label="Permalink to &quot;议题一：小对象内联存储（Tiny RGW Objects Packing）&quot;">​</a></h2><p><strong>提出者：Gaby</strong></p><p>当前 RGW 对于小于 512 字节的对象，仍会在磁盘上分配 block 存储数据。在 erasure coding 场景下（例如 4+2 配置），一个 256 字节的对象实际会消耗约 24 KB 的存储空间，代价极高。即便是 replication 模式，也需要支付 4 KB 的最小 block 开销。</p><p><strong>核心思路：</strong></p><p>观察到 RGW 对象的 manifest 本身约为 320 字节。若对象数据小于该阈值，可以将数据直接存储在 xattr（扩展属性）中，并省去 manifest，实现&quot;零额外开销&quot;的存储。在 BlueStore 中，xattr 存储于 RocksDB 的 Omap 中，不受 block 对齐限制，因此字节级别的数据存储是可行的。</p><p><strong>讨论要点：</strong></p><ul><li>实际使用场景确实存在：ProtonMail 将邮件作为 object 存储于 RGW，Spark 等引擎使用小对象作为文件标记，S3 用户也可能将小文件直接存为对象。</li><li>阈值建议在 320 字节到 512 字节之间，具体数值待定。</li><li>对 versioned bucket 无影响，每个版本有独立的 head object 和 xattr。</li><li>主要挑战是<strong>向后兼容性</strong>：新版本 RGW 写入的内联对象，旧版本无法识别。建议通过 zone feature flag 机制，在集群完成升级后再启用该特性，防止混版本集群出现读取异常。</li></ul><p><strong>结论：</strong> 思路可行，需进一步确定阈值并设计兼容性保护机制。</p><h2 id="议题二-multipart-upload-数据丢失问题" tabindex="-1">议题二：Multipart Upload 数据丢失问题 <a class="header-anchor" href="#议题二-multipart-upload-数据丢失问题" aria-label="Permalink to &quot;议题二：Multipart Upload 数据丢失问题&quot;">​</a></h2><p><strong>提出者：Casey（会议主持）</strong></p><p><strong>问题描述：</strong></p><p>客户报告了一个数据丢失的复现路径：第一次 complete multipart upload 请求在恰好 10 分钟后超时，客户端重试并发起新的 complete multipart upload，覆盖了原始的 multipart head object，导致原始上传的 tail objects 被垃圾回收删除。</p><p>10 分钟的超时与 RGW 使用的 CLS lock 时长一致——该锁用于保护 multipart upload 操作，但时间锁在到期后即失去保护效果，存在竞态窗口。</p><p><strong>根因分析：</strong></p><ul><li>multipart meta object 与最终 head object 分属不同 RADOS object，无法原子化操作。</li><li>multipart meta object 存储于 extra data pool，与 head object 不在同一 pool，因此无法通过 object locator key 强制同 PG。</li><li>当前 PR尝试通过 compare-and-swap（CMPX）方式拒绝覆盖 head object，但存在局限性：OSD 对不存在对象的 CLS read 行为不确定，且仍有其他竞态路径。</li></ul><p><strong>讨论的解决方案：</strong></p><ol><li><strong>CLS 实现类 CMPX 语义</strong>：在 CLS 中实现类似 compare-and-swap 的操作，但存在向后兼容问题，RGW 需要感知 OSD 是否支持该特性。</li><li><strong>持续约 CLS lock</strong>：参考 multi-site 中的做法，在 complete/abort multipart upload 期间每隔约 5 分钟续约一次锁，防止锁过期。这是目前最被认可的方向。</li><li><strong>返回限流错误码</strong>：当锁竞争时，将 500 错误改为限流错误码，引导客户端退避重试，减少竞争。</li><li><strong>引用计数防止 GC</strong>：通过 ref count 阻止 tail objects 被垃圾回收，但被认为实现复杂度过高，不可行。</li></ol><p><strong>关于并发量的担忧：</strong></p><p>有人担心为每个 multipart upload 请求启动续约 coroutine 会导致大量并发 coroutine。Casey 指出，complete multipart upload 本身已受 max concurrent requests 限制，续约 coroutine 数量上限与此相同，且 coroutine 本身轻量，影响可控。</p><p><strong>结论：</strong> Casey 将原型实现&quot;持续续约 CLS lock&quot;方案，同时考虑将锁竞争时的错误码改为限流码。</p><h2 id="议题三-keystone-角色注入-iam-policy" tabindex="-1">议题三：Keystone 角色注入 IAM Policy <a class="header-anchor" href="#议题三-keystone-角色注入-iam-policy" aria-label="Permalink to &quot;议题三：Keystone 角色注入 IAM Policy&quot;">​</a></h2><p><strong>提出者：Supriti（来自 Place，首次参会）</strong></p><p><strong>背景：</strong></p><p>当前 RGW 使用 Keystone 进行用户认证，仅判断用户是否具有 admin/reader 等角色，认证通过后角色信息即被丢弃，无法用于细粒度的访问控制。</p><p><strong>方案：</strong></p><p>将 Keystone 返回的角色列表注入到 IAM policy 的 environment（多值 map）中，在 policy 解析时通过条件键（condition key）进行匹配。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>条件：keystone:roles 包含 &quot;reader&quot;</span></span>
<span class="line"><span>效果：允许对特定 bucket 执行只读操作</span></span></code></pre></div><p>已提交 ADR 文档和 PR，并包含单元测试（复用 IAM 现有测试框架）。</p><p><strong>讨论要点：</strong></p><ul><li>建议为条件键添加命名前缀（如 <code>X-RGW-</code>）以避免与其他系统冲突，Supriti 已使用 <code>keystone:roles</code> 格式。</li><li>对外部 policy linter/validator 的兼容性可能存在影响，但属于工具侧问题。</li><li>关于未来扩展到基于 Keystone user ID 的访问控制，与会者认为需要进一步评估用例合理性，暂不纳入本次 PR。</li></ul><p><strong>结论：</strong> 方案简洁，社区反馈正面，将推进 PR 合并，user ID 粒度控制留待后续讨论。</p><h2 id="议题四-olh-epoch-一致性修复-versioned-bucket" tabindex="-1">议题四：OLH Epoch 一致性修复（Versioned Bucket） <a class="header-anchor" href="#议题四-olh-epoch-一致性修复-versioned-bucket" aria-label="Permalink to &quot;议题四：OLH Epoch 一致性修复（Versioned Bucket）&quot;">​</a></h2><p><strong>提出者：Jane</strong></p><p><strong>问题描述：</strong></p><p>在 versioned bucket 场景下，观察到 non-current 版本的 OLH（Object Lifecycle Head）entry epoch 新于 current 版本，导致后续 link OLH 操作无法将正确版本提升为 current。该问题在本地 zone 和 multi-site 复制场景下均可复现，触发条件为 S3 客户端流量、LC（Lifecycle）删除或 <code>radosgw-admin object rm</code> 命令。</p><p><strong>根因：</strong></p><p>执行 unlink instance 时，代码始终将 OLH entry 的 epoch 更新为最新值，导致 epoch 与其所指向的 instance 的实际 epoch 不一致，进而阻止更早版本被正确提升。</p><p><strong>修复方案：</strong></p><p>保持 OLH entry 的 epoch 与其所指向的 instance epoch 一致；pending log 中的 epoch 仍使用操作发生时的最新 epoch，以维持日志的时序回放能力。</p><p>这意味着 OLH epoch 可能在删除最新版本后&quot;回退&quot;到更早的值，这是预期行为——确保后续 link 操作能够正确比较并提升新版本。</p><p><strong>关于 epoch 单位的讨论：</strong></p><p>早期 PR 已将 OLH data entry epoch 和 candidate epoch 统一转换为基于时间戳的格式，因此两者比较单位一致，不存在混用问题。</p><p><strong>测试覆盖：</strong></p><p>当前测试使用 <code>radosgw-admin object rm</code> 复现问题，S3 delete 请求无法复现（原因待查）。Casey 建议后续补充 S3 delete 路径的测试用例。</p><p><strong>结论：</strong> Igor 和团队内部已讨论确认，方案合理，待补充测试覆盖后合并。</p><h2 id="议题五-multi-site-复制流量负载均衡-dns-服务发现场景" tabindex="-1">议题五：Multi-site 复制流量负载均衡（DNS 服务发现场景） <a class="header-anchor" href="#议题五-multi-site-复制流量负载均衡-dns-服务发现场景" aria-label="Permalink to &quot;议题五：Multi-site 复制流量负载均衡（DNS 服务发现场景）&quot;">​</a></h2><p><strong>提出者：Ogazon</strong></p><p><strong>问题背景：</strong></p><p>multi-site 复制底层使用 libcurl 拉取数据。libcurl 在解析 DNS 端点时，默认只取单个 IP 并维持久连接，导致在使用 DNS 服务发现（而非负载均衡器）的场景下，复制流量集中打到少数几个 RGW 节点，形成热点。</p><p><strong>三种典型部署模式：</strong></p><ol><li><strong>枚举所有 RGW 实例 IP</strong>：流量均匀分布，无热点，但运维成本高。</li><li><strong>单端点 + 负载均衡器</strong>：流量均匀，但负载均衡器成本高且引入额外复杂度。</li><li><strong>单端点 + DNS 服务发现</strong>（当前用户场景）：libcurl 只解析到单个 IP，导致流量不均。</li></ol><p><strong>提出的解决方案：</strong></p><p>在 RGW 侧主动将 DNS 端点解析为所有可用 IP，利用 libcurl 的 <code>--connect-to</code> 选项，在发起请求时指定目标 IP，并在 RGW 层实现轮询（round-robin）逻辑，将复制流量均匀分发到所有节点。</p><p>初步 POC 测试结果显示，使用该方案后复制流量可均匀分布到所有 RGW 实例。</p><p><strong>实现挑战：</strong></p><p>当前 RGW 将 endpoint 表示为单一 URL字符串，需要对 RGW 内部的 HTTP 客户端代码进行一定程度的重构，以支持传递 <code>connect-to</code> hint 给 libcurl。</p><p><strong>结论：</strong> 问题动机充分，方案思路清晰，实现细节较复杂。Casey 表示将尝试在 PR 上留下反馈，下次会议继续深入讨论。</p><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>负责人</th><th>行动项</th></tr></thead><tbody><tr><td>Casey</td><td>原型实现 multipart upload CLS lock 持续续约方案</td></tr><tr><td>Casey</td><td>评估将锁竞争错误码改为限流码</td></tr><tr><td>Supriti</td><td>推进 Keystone 角色注入 IAM policy 的 PR合并</td></tr><tr><td>Jane</td><td>补充 OLH epoch 修复的 S3 delete 路径测试用例</td></tr><tr><td>Ogazon</td><td>整理 DNS 服务发现负载均衡 PR，下次会议深入讨论</td></tr><tr><td>Gabby</td><td>进一步调研小对象内联存储的实际使用规模及阈值选择</td></tr></tbody></table>`,61)])])}const h=e(n,[["render",p]]);export{u as __pageData,h as default};
